draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // grandparent
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 + 20, H/2 + 70);
  ctx.stroke();

  // parent
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // child
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + W/4, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + W/4, H/2 + 20);
  ctx.lineTo(W/2 + W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + W/4, H/2 + 50);
  ctx.lineTo(W/2 + W/4 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + W/4, H/2 + 50);
  ctx.lineTo(W/2 + W/4 + 20, H/2 + 70);
  ctx.stroke();

  // breaking cycle
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/2 + W/4 + 20, H/2 + 70);
  ctx.lineTo(W/2 + W/4 + 20 + 50*Math.cos(t), H/2 + 70 + 50*Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
